import type { MessageKey, Tr } from '../../i18n';

/**
 * Types and pure helpers of the /docs page (product documentation).
 * The manifest is generated by frontend/scripts/build-docs.mjs from DOCUMENTATION/.
 *
 * The **search** is not here: it lives in `docsSearch`, shared by the page's table of contents
 * and the Ctrl+K palette. Two surfaces, one engine.
 */

export interface DocsPage {
  path: string; // relative path within /docs (e.g. "user-guide/review-video.md")
  title: string;
  summary: string; // one-line subtitle, rendered under the title and matched by the filter
  updated: string; // ISO date of the page's "Updated:" line, '' if the page has none
  /**
   * Chapter headings: the table of contents of the page, the only index of its **content**
   * (cf. `pageHeadings` in `scripts/build-docs.mjs`). Optional: a manifest produced by an
   * earlier build stays servable, and the page is then searched by its title alone.
   */
  headings?: string[];
}

export interface DocsSection {
  dir: string; // "" for the root (README)
  label: string;
  pages: DocsPage[];
}

export interface DocsManifest {
  generatedAt: string;
  sections: DocsSection[];
}

/**
 * Translated label of a section. The manifest carries one, derived from the folder name and
 * therefore in English like the documentation; the interface, however, follows the reader's
 * language. An unknown folder keeps the manifest label.
 */
const SECTION_LABEL_KEY: Record<string, MessageKey> = {
  '': 'docs.sectionOverview',
  'getting-started': 'docs.sectionGettingStarted',
  'user-guide': 'docs.sectionUserGuide',
  'admin-guide': 'docs.sectionAdminGuide',
  api: 'docs.sectionApi',
  infrastructure: 'docs.sectionInfrastructure',
  development: 'docs.sectionDevelopment',
};

export function sectionLabel(section: Pick<DocsSection, 'dir' | 'label'>, t: Tr): string {
  const key: MessageKey | undefined = SECTION_LABEL_KEY[section.dir];
  return key ? t(key) : section.label;
}

/** Resolves a relative markdown page href to a doc path ("a/b.md" + "../c/d.md" → "c/d.md"). */
export function resolveDocHref(currentPath: string, href: string): string {
  const [pathPart, hash] = href.split('#');
  const baseSegments = currentPath.split('/').slice(0, -1);
  for (const seg of pathPart.split('/')) {
    if (seg === '' || seg === '.') continue;
    if (seg === '..') baseSegments.pop();
    else baseSegments.push(seg);
  }
  const resolved = baseSegments.join('/');
  return hash ? `${resolved}#${hash}` : resolved;
}

/** Internal doc href: relative (neither a protocol, a bare anchor, nor an absolute path). */
export function isInternalDocHref(href: string): boolean {
  return !/^([a-z]+:|\/|#)/i.test(href);
}

/** The section containing a page: the one whose side panel must stay open. */
export function sectionOf(sections: DocsSection[], path: string): DocsSection | undefined {
  return sections.find((s) => s.pages.some((p) => p.path === path));
}

/** Previous and next page in table-of-contents order, with sections chained together. */
export function neighbours(sections: DocsSection[], path: string): { previous?: DocsPage; next?: DocsPage } {
  const flat = sections.flatMap((s) => s.pages);
  const i = flat.findIndex((p) => p.path === path);
  if (i === -1) return {};
  return { previous: flat[i - 1], next: flat[i + 1] };
}
